def solve(s):
    """Run-length encoding for strings and generic iterables.
    Returns a list of [element, count] pairs.
    If the input is not iterable (or is None), returns an empty list.
    """
    # Handle None or non-iterable inputs gracefully
    if s is None:
        return []
    # Strings are iterable, but also need to treat other iterables
    try:
        iterator = iter(s)
    except TypeError:
        return []
    # Obtain first element
    try:
        cur = next(iterator)
    except StopIteration:
        return []
    cnt = 1
    res = []
    for ch in iterator:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
    res.append([cur, cnt])
    return res

