def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search for O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an LIS of length i+1
    for x in nums:
        # find insertion point (first element >= x) because we need strict increase
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

