def solve(tokens):
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncates toward zero without using float
                # compute absolute division then apply sign
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                res = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    res = -res
                stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

